{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The Introduction describes the current state of knowledge (systems science calls, prior SD reviews in public health) and identifies the key uncertainty/gap: the application of SD modeling to cancer prevention and control has not been studied."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The need for the review is explained: complexity of cancer requires systems approaches, and the specific application of SD to cancer prevention and control is unexamined, motivating the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Prior reviews are cited [24, 25] and differentiated from the current review (they covered public health broadly, not cancer specifically), but the reviews are not described in detail as previous systematic reviews of the same topic; the distinction is made implicitly."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a methods review of system dynamics modeling applications, not a review of intervention effects, so no intervention mechanism of action needs to be described."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a specific complex intervention or delivery context; it reviews modeling methods, so a logic model of intervention components is not applicable."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement of review objectives or questions is provided. The abstract notes a gap ('the breadth, characteristics, and quality of these studies is not known') and the introduction ends with 'The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied,' but neither states an explicit objective or research question, nor uses a question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This is a methods/characteristics review of system dynamics modeling applications, not a review of intervention effects, so planned comparisons in PICO format do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "Eligible designs (system dynamics modeling types) and topic (cancer prevention or control) are specified, but settings, populations, and other question-framework components (e.g., outcomes, comparisons) are not detailed."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "Report characteristics are specified: peer-reviewed status, English language, and dissemination within the last 10 years."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review)",
      "reason": "Synthesis groups (simulation vs diagram-only; topics mapped onto the cancer control continuum) are described, but the grouping is presented in Results rather than specified in Methods and is not explicitly linked to comparisons defined in review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This search period was selected to reflect recent developments and current applications of system dynamics modeling related to cancer.",
      "reason": "A rationale is provided for the 10-year restriction on publication date; the Limitations section also explains the rationale for excluding non-cancer topics and pathogenesis-only studies."
    }
  ],
  "confidence": 85
}

